import math
from math import sqrt

def prime(n):
	prime_flag = 0
	if n > 1:
		for i in range(2, int(sqrt(n)) + 1):
			if n % i == 0:
				prime_flag = 1
				break
		if prime_flag == 0:
			return True
		else:
			return False
	else:
		return False

def printDivisors(n):
	i = 2
	d = []
	while i <= math.sqrt(n):
		if n % i == 0:
			if n / i == i:
				return i
			else:
				return min(i, n // i)
		i = i + 1
	return d
for i in range(int(input())):
	m = int(input())
	if prime(m):
		print(m + 1)
	else:
		w = printDivisors(m)
		print((w + 1) * (m // w))
